(7030178, 1067974, 157652, '<td valign="top">My favorite entry in the challenge.</td>', 'My favorite entry in the challenge.', '2013-05-01 01:28:08.000000', NULL, 1),
(7030188, 1067900, 157652, '<td valign="top">Is that the Space Needle in the background? Beautiful.</td>', 'Is that the Space Needle in the background? Beautiful.', '2013-05-01 01:36:25.000000', NULL, 1),
(7030467, 1067914, 114225, '<td valign="top">A cool looking fountain, but the composition is flat to me.</td>', 'A cool looking fountain, but the composition is flat to me.', '2013-05-01 14:22:35.000000', NULL, 1),
(7030468, 1067609, 114225, '<td valign="top">Oh, a human element I didn''t expect. Nice touch.</td>', 'Oh, a human element I didn''t expect. Nice touch.', '2013-05-01 14:22:52.000000', NULL, 1),
(7030469, 1067929, 114225, '<td valign="top">Even a non-operating fountain can look nice. Good find.</td>', 'Even a non-operating fountain can look nice. Good find.', '2013-05-01 14:23:22.000000', NULL, 1),
(7030470, 1067863, 114225, '<td valign="top">I have a feeling this is actually just a rock being thrown into the water, but it''s a creative idea to try to meet the challenge.</td>', 'I have a feeling this is actually just a rock being thrown into the water, but it''s a creative idea to try to meet the challenge.', '2013-05-01 14:24:40.000000', NULL, 1),
(7030472, 1067787, 114225, '<td valign="top">I like the idea of using the shallow depth of field here. But I find that the B&amp;W conversion lacks contrast. Some more deep blacks could help.</td>', 'I like the idea of using the shallow depth of field here. But I find that the B&W conversion lacks contrast. Some more deep blacks could help.', '2013-05-01 14:26:31.000000', NULL, 1),
(7030473, 1067756, 114225, '<td valign="top">Good contrast, in two different meanings of the word.</td>', 'Good contrast, in two different meanings of the word.', '2013-05-01 14:26:57.000000', NULL, 1),
(7030474, 1067189, 114225, '<td valign="top">Wonderful image. That girl adds so much to the scene.</td>', 'Wonderful image. That girl adds so much to the scene.', '2013-05-01 14:27:57.000000', NULL, 1),
(7030475, 1067671, 114225, '<td valign="top">Wow! What an amazing work of art!</td>', 'Wow! What an amazing work of art!', '2013-05-01 14:28:08.000000', NULL, 1),
