(7032168, 1067756, 30712, '<td valign="top">Very good use of light, shade and silhouette.  A quality image.</td>', 'Very good use of light, shade and silhouette.  A quality image.', '2013-05-05 03:04:57.000000', NULL, 1),
(7032169, 1067176, 30712, '<td valign="top">With a background as messy as this I would have spent some time moving about to find a better one.  Another idea would be to throw the background out of focus by limiting the depth of field.  A tall vertical format image might have improved things as well.</td>', 'With a background as messy as this I would have spent some time moving about to find a better one.  Another idea would be to throw the background out of focus by limiting the depth of field.  A tall vertical format image might have improved things as well.', '2013-05-05 03:08:51.000000', NULL, 1),
